from pathlib import Path
import base64

path = Path("app/(portal)/game/components/HouseOfChancesPanel.tsx")

if not path.exists():
    raise SystemExit(f"Missing expected file: {path}")

text = path.read_text(encoding="utf-8")

start = text.find('  return (\n    <details')
if start < 0:
    raise SystemExit("Could not find House of Chances render block.")

end_marker = '\n  );\n}\n'
end = text.find(end_marker, start)
if end < 0:
    raise SystemExit("Could not find end of House of Chances component.")

new_render = base64.b64decode('').decode("utf-8")
text = text[:start] + new_render + text[end + len("\n  );"):]

path.write_text(text, encoding="utf-8")

print("SUCCESS")
print("House of Chances showcase visual redesign applied.")
print("No RPC, rules, rewards, wallet or ledger logic changed.")
print("Now run: npm run build")
